head.script:
//
(function () {
    document.documentElement.classList.add('teidesat-loading');
    var t = setTimeout(function () {
        document.documentElement.classList.remove('teidesat-loading');
    }, 400);
    function reveal() {
        clearTimeout(t);
        document.documentElement.classList.remove('teidesat-loading');
        var g = document.getElementById('teidesat-fouc-guard');
        if (g) g.remove();
    }
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', reveal, { once: true });
    } else {
        reveal();
    }
})();
//

div.script:
//
(function () {
    'use strict';

    var REVEAL    = 'reveal-up';
    var VISIBLE   = 'is-visible';
    var MOBILE_BP = 767;
    var SNAP_DELAY = 400;

    /* ────────────────────────────────────────────────────────────
       MENÚ — Solo se inicializa UNA VEZ.
       Re-inicializar en cada navegación duplica los listeners
       y rompe el toggle en Odoo pjax.
    ──────────────────────────────────────────────────────────── */
    var menuReady = false;

    function initMenu() {
        if (menuReady) return;

        var toggle  = document.getElementById('teidesat-menu-toggle');
        var close   = document.getElementById('teidesat-menu-close');
        var overlay = document.getElementById('teidesat-menu-overlay');
        var menu    = document.getElementById('teidesat-side-menu');
        if (!toggle || !menu) return;

        function openMenu() {
            menu.classList.add('is-open');
            if (overlay) overlay.classList.add('is-open');
            document.body.classList.add('teidesat-menu-open');
            toggle.setAttribute('aria-expanded', 'true');
            menu.setAttribute('aria-hidden', 'false');
        }

        function closeMenu() {
            menu.classList.remove('is-open');
            if (overlay) overlay.classList.remove('is-open');
            document.body.classList.remove('teidesat-menu-open');
            toggle.setAttribute('aria-expanded', 'false');
            menu.setAttribute('aria-hidden', 'true');
        }

        toggle.addEventListener('click', openMenu);
        if (close)   close.addEventListener('click', closeMenu);
        if (overlay) overlay.addEventListener('click', closeMenu);

        menu.querySelectorAll('a').forEach(function (a) {
            a.addEventListener('click', closeMenu);
        });

        menuReady = true;
    }

    /* ── Botón volver arriba ────────────────────────────────── */
    var backtopReady = false;

    function initBacktop() {
        if (backtopReady) return;
        var btn = document.getElementById('teidesat-backtop');
        if (!btn) return;
        btn.addEventListener('click', function (e) {
            e.preventDefault();
            window.scrollTo({ top: 0, behavior: 'smooth' });
        });
        backtopReady = true;
    }

    /* ── Limpiar opacity/visibility inline de Odoo ─────────── */
    function clearOdooOverlay() {
        ['wrapwrap', 'wrap'].forEach(function (id) {
            var el = document.getElementById(id);
            if (!el) return;
            el.style.removeProperty('opacity');
            el.style.removeProperty('visibility');
            el.style.removeProperty('transition');
            el.style.removeProperty('transform');
            el.style.removeProperty('pointer-events');
        });
        document.querySelectorAll('main,.teidesat-main,.o_main_content').forEach(function (el) {
            el.style.removeProperty('opacity');
            el.style.removeProperty('visibility');
        });
    }

    /* ── Forzar viewport correcto en móvil ────────────────────── */
    function fixViewport() {
        var metas = document.head.querySelectorAll('meta[name="viewport"]');
        var correct = 'width=device-width, initial-scale=1, maximum-scale=5, viewport-fit=cover';

        /* Eliminar todos los duplicados y dejar solo uno */
        if (metas.length > 1) {
            for (var i = 1; i < metas.length; i++) {
                metas[i].parentNode.removeChild(metas[i]);
            }
        }

        if (metas.length === 0) {
            /* No existe ninguno — crearlo */
            var m = document.createElement('meta');
            m.name = 'viewport';
            m.content = correct;
            document.head.insertBefore(m, document.head.firstChild);
        } else if (metas[0].content !== correct) {
            /* Existe pero con contenido incorrecto — corregirlo */
            metas[0].content = correct;
        }
    }

    /* ── Scroll al top + gestión del snap ──────────────────── */
    var snapTimer = null;

    function resetScroll() {
        document.body.classList.remove('snap-ready');
        window.scrollTo(0, 0);
        document.documentElement.scrollTop = 0;
        document.body.scrollTop = 0;
        var ww = document.getElementById('wrapwrap');
        if (ww) ww.scrollTop = 0;

        clearTimeout(snapTimer);
        snapTimer = setTimeout(function () {
            var path = window.location.pathname;
            if (path === '/' || path === '') {
                document.body.classList.add('snap-ready');
            }
        }, SNAP_DELAY);
    }

    /* ── Reveal-up ──────────────────────────────────────────── */
    var io = null;

    function triggerReveal() {
        var mobile = window.innerWidth <= MOBILE_BP;
        if (io) { io.disconnect(); io = null; }

        if (!mobile && window.IntersectionObserver) {
            io = new IntersectionObserver(function (entries) {
                entries.forEach(function (e) {
                    if (e.isIntersecting) {
                        e.target.classList.add(VISIBLE);
                        io.unobserve(e.target);
                    }
                });
            }, { threshold: 0.08 });
        }

        document.querySelectorAll('.' + REVEAL).forEach(function (el) {
            if (mobile) {
                el.classList.add(VISIBLE);
            } else if (!el.classList.contains(VISIBLE)) {
                if (io) io.observe(el);
                else    el.classList.add(VISIBLE);
            }
        });
    }

    /* ── Inicialización de página (se llama en cada navegación) */
    function initPage() {
        fixViewport();        /* <-- FIX viewport antes de todo */
        clearOdooOverlay();
        resetScroll();
        triggerReveal();
    }

    /* ── Arranque inicial (una sola vez, incluye menú) ──────── */
    function boot() {
        fixViewport();
        clearOdooOverlay();
        resetScroll();
        triggerReveal();
        initMenu();
        initBacktop();
    }

    /* ── Disparadores ───────────────────────────────────────── */

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', boot);
    } else {
        boot();
    }
    window.addEventListener('load', function () { setTimeout(boot, 30); });

    window.addEventListener('resize', function () {
        fixViewport();
        clearOdooOverlay();
        triggerReveal();
        var path = window.location.pathname;
        if (path === '/' || path === '') {
            document.body.classList.add('snap-ready');
        } else {
            document.body.classList.remove('snap-ready');
        }
    });

    window.addEventListener('orientationchange', function () {
        setTimeout(initPage, 250);
    });

    /* Interceptar history API (SPA / pjax de Odoo) */
    ['pushState', 'replaceState'].forEach(function (method) {
        var orig = history[method].bind(history);
        history[method] = function () {
            orig.apply(this, arguments);
            setTimeout(initPage,  60);
            setTimeout(initPage, 380);
        };
    });
    window.addEventListener('popstate', function () { setTimeout(initPage, 60); });

    /* Eventos internos de Odoo website */
    ['page:load', 'content_changed', 'website.dom_ready', 'dom_updated'].forEach(function (e) {
        document.addEventListener(e, initPage);
    });

    /* MutationObserver — detecta inyección de contenido nuevo.
       Ignora nodos del menú y decorativos para evitar bucles
       que duplicaban listeners en versiones anteriores. */
    var ignoredIds     = ['teidesat-menu-toggle', 'teidesat-menu-close',
                          'teidesat-menu-overlay', 'teidesat-side-menu',
                          'teidesat-backtop'];
    var ignoredClasses = ['hs-star', 'hs-stars', 'is-open', 'is-visible',
                          'teidesat-loading'];

    new MutationObserver(function (mutations) {
        var hit = mutations.some(function (m) {
            if (m.type !== 'childList') return false;
            for (var i = 0; i < m.addedNodes.length; i++) {
                var n = m.addedNodes[i];
                if (n.nodeType !== 1) continue;
                if (n.id && ignoredIds.indexOf(n.id) !== -1) continue;
                var skip = false;
                if (n.classList) {
                    for (var j = 0; j < ignoredClasses.length; j++) {
                        if (n.classList.contains(ignoredClasses[j])) { skip = true; break; }
                    }
                }
                if (!skip) return true;
            }
            return false;
        });
        if (hit) setTimeout(initPage, 60);
    }).observe(document.body, { childList: true, subtree: true });

})();
//
